			if(false){
				this.vel.x = cos(angle)*facteurNoise+random(-1,1)*facteurRandom
				this.vel.y = sin(angle)*facteurNoise+random(-1,1)*facteurRandom
			}else{
				this.vel.x = cos(angle)
