function exportSVGOptimise() {
  // Démarrer l'enregistrement SVG
  if (printSVG) {
    beginRecordSVG(this, fileName + floor(performance.now()) + ".svg");
    setSvgDefaultStrokeWeight(0.1);
    setSvgDefaultStrokeColor('black');
    setSvgFlattenTransforms(true);
  }

  // Redessiner avec des paths optimisés
  clear();
  background(255);
  noFill();
  stroke(0);
  strokeWeight(0.1);

  for (let i = 0; i < cheminsParParticule.length; i++) {
    let cheminParticule = cheminsParParticule[i];

    if (cheminParticule.points.length > 1) {
      beginShape();
      for (let j = 0; j < cheminParticule.points.length; j++) {
        vertex(cheminParticule.points[j].x, cheminParticule.points[j].y);
      }
      endShape();
    }
  }

  // Terminer l'enregistrement SVG
  if (printSVG) {
    endRecordSVG();
  }

  noLoop();
}

