  var functionName = "Penner's Ease-Out Back";

  var s = 1.70158;
  x = x - 1.0;
  var y = (x * x * ((s + 1.0) * x + s) + 1.0);
  return y;
}

//------------------------------------------------------------------
function brycePolynomial(x, n) {
  var functionName = "Bryce's Cubic";

  let xnm1 = pow(x, n - 1);
  let xn = xnm1 * x;

  return n * xnm1 - (n - 1) * xn;
}

//------------------------------------------------------------------
function pennerEaseInOutBack(x) {
  var functionName = "Penner's EaseInOut Back";

  var s = 1.70158 * 1.525;
  x /= 0.5;

  var y = 0;
  if (x < 1) {
    y = 1.0 / 2.0 * (x * x * ((s + 1.0) * x - s));
  } else {
    x -= 2.0;
    y = 1.0 / 2.0 * (x * x * ((s + 1.0) * x + s) + 2.0);
  }
  return y;
}

//------------------------------------------------------------------
function pennerEaseInQuadratic(t) {
  var functionName = "Penner's EaseIn Quadratic";
