}

//------------------------------------------------------------------
function pennerEaseInOutQuadratic(t) {
  var functionName = "Penner's EaseInOut Quadratic";
  if ((t /= 1.0 / 2) < 1) {
    return 1.0 / 2 * t * t;
  } else {
    return -1.0 / 2 * ((--t) * (t - 2) - 1);
  }
}

//------------------------------------------------------------------
function pennerEaseInCubic(x) {
