}

//------------------------------------------------------------------
function pennerEaseInOutCubic(x) {
  var functionName = "Penner's EaseInOut Cubic";

  x *= 2.0;
  var y = 0;

  if (x < 1) {
    y = 0.5 * x * x * x;
  } else {
    x -= 2.0;
    y = 0.5 * (x * x * x + 2.0);
  }
  return y;
}

//------------------------------------------------------------------
function pennerEaseInQuartic(t) {
  var functionName = "Penner's EaseIn Quartic";
  return t * t * t * t;
}

//------------------------------------------------------------------
function pennerEaseOutQuartic(t) {
  var functionName = "Penner's EaseOut Quartic";
  return -1.0 * ((t = t - 1) * t * t * t - 1.0);
}

//------------------------------------------------------------------
function pennerEaseInOutQuartic(t) {
  var functionName = "Penner's EaseInOut Quartic";

  if ((t /= 1.0 / 2.0) < 1) return 1.0 / 2.0 * t * t * t * t;
  return -1.0 / 2.0 * ((t -= 2.0) * t * t * t - 2.0);
}

//------------------------------------------------------------------
function pennerEaseInQuintic(t) {
  var functionName = "Penner's EaseIn Quintic";
  return t * t * t * t * t;
}

//------------------------------------------------------------------
function pennerEaseOutQuintic(t) {
  var functionName = "Penner's EaseOut Quintic";
  t = t - 1;
  return (t * t * t * t * t + 1.0);
}

//------------------------------------------------------------------
function pennerEaseInOutQuintic(t) {
  var functionName = "Penner's EaseInOut Quintic";
  if ((t /= 1.0 / 2) < 1) return 1.0 / 2 * t * t * t * t * t;
  return 1.0 / 2 * ((t -= 2) * t * t * t * t + 2);
}

//------------------------------------------------------------------
function pennerEaseInSine(t) {
  var functionName = "Penner's EaseIn Sine";
  return -1.0 * cos(t * (PI / 2)) + 1;
}

//------------------------------------------------------------------
function pennerEaseOutSine(t) {
  var functionName = "Penner's EaseOut Sine";
  return sin(t * (PI / 2));
}

//------------------------------------------------------------------
function pennerEaseInOutSine(t) {
  var functionName = "Penner's EaseInOut Sine";
  return -0.5 * (cos(PI * t) - 1);
}

//------------------------------------------------------------------
function pennerEaseInExpo(t) {
  var functionName = "Penner's EaseIn Exponential";
  return (t == 0) ? 0 : pow(2, 10 * (t - 1));
}

//------------------------------------------------------------------
function pennerEaseOutExpo(t) {
  var functionName = "Penner's EaseOut Exponential";
  return (t == 1) ? 1 : (-pow(2, -10 * t) + 1);
}

//------------------------------------------------------------------
function pennerEaseInOutExpo(t) {
  var functionName = "Penner's EaseInOut Exponential";
  if (t == 0) return 0.0;
  if (t == 1) return 1.0;
  if ((t /= 1.0 / 2) < 1) return 1.0 / 2 * pow(2, 10 * (t - 1));
  return 1.0 / 2 * (-pow(2, -10 * --t) + 2);
}

//------------------------------------------------------------------
function pennerEaseInElastic(t) {
  var functionName = "Penner's EaseIn Elastic";

  if (t == 0) return 0.0;
  if (t == 1) return 1.0;
  var p = 0.3;

  var s = p / 4;
  var postFix = pow(2, 10.0 * (t -= 1)); // this is a fix, again, with post-increment operators
  return -(postFix * sin((t - s) * (2 * PI) / p));
}

//------------------------------------------------------------------
function pennerEaseOutElastic(t) {
  var functionName = "Penner's EaseOut Elastic";

  if (t == 0) return 0.0;
  if (t == 1) return 1.0;
  var p = 0.3;
  var s = p / 4;

  return (pow(2, -10 * t) * sin((t - s) * (2 * PI) / p) + 1);
}

//------------------------------------------------------------------
function pennerEaseInOutElastic(t) {
  var functionName = "Penner's EaseInOut Elastic";

  if (t == 0) return 0;
  if ((t /= 0.5) == 2) return 1;
  var p = (.3 * 1.5);
  var a = 1;
  var s = p / 4;

  if (t < 1) {
    var postFix = pow(2, 10 * (t -= 1)); // postIncrement is evil
    return -0.5 * (postFix * sin((t - s) * (2 * PI) / p));
  }
  var postFix = pow(2, -10 * (t -= 1)); // postIncrement is evil
  return postFix * sin((t - s) * (2 * PI) / p) * .5 + 1;
}



//------------------------------------------------------------------
function pennerEaseOutBounce(t) {
  var functionName = "Penner's EaseOut Bounce";

  if ((t) < (1 / 2.75)) {
    return (7.5625 * t * t);
  } else if (t < (2 / 2.75)) {
    var postFix = t -= (1.5 / 2.75);
    return (7.5625 * (postFix) * t + 0.75);
  } else if (t < (2.5 / 2.75)) {
    var postFix = t -= (2.25 / 2.75);
    return (7.5625 * (postFix) * t + 0.9375);
  } else {
    var postFix = t -= (2.625 / 2.75);
    return (7.5625 * (postFix) * t + 0.984375);
  }
}

//------------------------------------------------------------------
function pennerEaseInBounce(t) {
  var functionName = "Penner's EaseIn Bounce";
  return (1.0 - pennerEaseOutBounce(1.0 - t));
}

//------------------------------------------------------------------
function pennerEaseInOutBounce(t) {
  var functionName = "Penner's EaseInOut Bounce";
  if (t < 0.5) {
    return pennerEaseInBounce(t * 2) * .5;
  } else {
    return pennerEaseOutBounce(t * 2 - 1) * .5 + .5;
  }
}

//------------------------------------------------------------------
function staircase(x, n) {
  var functionName = "Staircase";
  var y = floor(x * n) / (float)(n - 1);
  return y;
}

//------------------------------------------------------------------
function exponentialSmoothedStaircase(x, a, n) {
  var functionName = "Smoothed Exponential Staircase";
  // See http://web.mit.edu/fnl/volume/204/winston.html

  var fa = sq(map(a, 0, 1, 5, 30));
  var y = 0;
  for (let i = 0; i < n; i++) {
    y += (1.0 / (n - 1.0)) / (1.0 + exp(fa * (((i + 1.0) / n) - x)));
  }
  y = constrain(y, 0, 1);
  return y;
}

//------------------------------------------------------------------
function gompertz(x, a) {
  // http://en.wikipedia.org/wiki/Gompertz_curve
  var functionName = "Gompertz Function";

  let min_param_a = 0.0 + Number.EPSILON;
  a = max(a, min_param_a);

  var b = -8.0;
  var c = 0 - a * 16.0;
  var y = exp(b * exp(c * x));

  var maxVal = exp(b * exp(c));
  var minVal = exp(b);
  y = map(y, minVal, maxVal, 0, 1);

  return y;
}

